// errSkillListed signals that skills were listed (non-interactive, no skill
// name given) and no installation should take place.
var errSkillListed = errors.New("skills listed")

// printSkillListing writes one skill per line as "name<sep>description".
// When tabSeparated is true, a tab is used as the separator so the output
// can be processed with standard text tools.
func printSkillListing(w io.Writer, skills []discovery.Skill, tabSeparated bool) {
	sep := " - "
	if tabSeparated {
		sep = "\t"
	}
	for _, s := range skills {
		desc := text.RemoveExcessiveWhitespace(s.Description)
		fmt.Fprintf(w, "%s%s%s\n", s.DisplayName(), sep, desc)
	}
}
